/** 话题洞察 Mock 报告（拜瑞妥心内科示例） */

export const TOPIC_INSIGHT_MOCK_REPORT = "# 拜瑞妥®心内科话题洞察报告（示例）\n\n## 整体洞察\n\n围绕当前心内科临床实践，建议重点关注**房颤卒中预防、长期抗凝管理、房颤合并冠心病、慢性冠心病残余血栓风险及泛血管管理**等方向。\n\n从内容策略上看，这些方向兼具以下特点：\n\n- 与心内科医生日常诊疗高度相关\n- 能自然体现拜瑞妥在相关疾病管理中的价值\n- 兼具学术深度与内容传播潜力\n- 适合延展为系列化内容，支持后续持续运营\n\n---\n\n## 01｜房颤患者的卒中预防：抗凝治疗如何真正实现长期获益？\n\n### 建议标题\n\n- **《心律失序之后，如何守住卒中的那道防线？》**\n- **《每一次不规则心跳，都值得看见它背后的卒中风险》**\n- **《房颤无声，卒中有迹：从风险识别走向主动预防》**\n- **《在卒中发生之前：房颤患者更需要怎样的长期守护？》**\n\n### 话题简要说明\n\n围绕非瓣膜性房颤患者卒中和全身性栓塞风险，从风险识别、抗凝决策到长期管理展开内容，帮助医生建立更加完整的房颤抗凝管理视角。\n\n### 品牌优势体现\n\n该方向与拜瑞妥在房颤卒中预防中的核心应用场景高度契合，能够自然承接“房颤—卒中预防—长期抗凝管理”这一临床主线。既具备疾病教育意义，也便于体现品牌在长期血栓风险管理中的专业形象。\n\n### 医生使用场景匹配度\n\n**★★★★★ 高**\n\n适合场景：\n\n- 房颤门诊\n- 心律失常门诊\n- 住院患者出院教育\n- 长期随访管理\n- 专家学术分享\n\n---\n\n## 02｜房颤抗凝不是“一次选择”：如何做好患者长期动态管理？\n\n### 建议标题\n\n- **《时间，是抗凝治疗中最容易被忽略的变量》**\n- **《一张处方之后：房颤患者真正漫长的治疗旅程》**\n- **《当治疗进入日常：如何让抗凝获益走得更远？》**\n- **《从一次选择，到一路守护：重新理解长期抗凝》**\n\n### 话题简要说明\n\n从长期随访视角讨论房颤患者风险变化、共病情况以及治疗管理，强调抗凝并非一次性决策，而是需要持续评估、动态管理和长期陪伴的过程。\n\n### 品牌优势体现\n\n这一方向弱化单纯产品介绍，更突出疾病长期管理价值。拜瑞妥可在“长期抗凝管理”的话题中自然出现，有助于塑造品牌在房颤慢病管理中的长期价值认知。\n\n### 医生使用场景匹配度\n\n**★★★★★ 高**\n\n适合场景：\n\n- 房颤长期随访\n- 慢病管理门诊\n- 抗凝管理门诊\n- 患者依从性教育\n- 学术科普内容运营\n\n---\n\n## 03｜房颤合并冠心病：面对“双重血栓风险”，临床决策如何更精细？\n\n### 建议标题\n\n- **《当房颤遇见冠心病：两种风险如何在同一位患者身上交汇？》**\n- **《一颗心脏，两重风险：复杂患者的抗栓之问》**\n- **《在卒中与冠脉事件之间，寻找更精细的平衡》**\n- **《当风险不再单线发生：房颤合并冠心病的临床思考》**\n\n### 话题简要说明\n\n聚焦心内科常见的复杂共病患者，通过房颤与冠心病同时存在的临床情境，引导医生关注不同类型血栓风险及患者分层管理，强调临床决策的复杂性与精细化趋势。\n\n### 品牌优势体现\n\n该方向能够很好地连接拜瑞妥在不同心血管相关场景中的疾病管理价值，帮助品牌从单一用药场景延展到更复杂的临床管理视角，增强专业度与学术讨论空间。\n\n### 医生使用场景匹配度\n\n**★★★★★ 高**\n\n适合场景：\n\n- 综合心内科\n- 复杂病例讨论\n- 共病患者管理\n- 专家病例分享\n- 学术会议内容传播\n\n---\n\n## 04｜稳定不等于低风险：慢性冠心病患者还需要关注什么？\n\n### 建议标题\n\n- **《平静之下，风险是否真的已经远去？》**\n- **《症状沉默之后：慢性冠心病仍需面对的长期风险》**\n- **《看似稳定的心脏，仍在经历怎样的风险考验？》**\n- **《从“没有症状”到“更少事件”：冠心病长期管理的下一程》**\n\n### 话题简要说明\n\n从“患者症状稳定，但长期心血管事件风险仍值得关注”的认知反差切入，引导医生讨论慢性冠心病患者在长期管理中面临的残余血栓风险和事件预防问题。\n\n### 品牌优势体现\n\n这一方向与拜瑞妥在冠心病长期风险管理中的定位具有较强契合度，能够帮助品牌从“治疗”进一步延展到“长期事件预防”和“持续血管保护”的价值表达。\n\n### 医生使用场景匹配度\n\n**★★★★★ 高**\n\n适合场景：\n\n- 冠心病门诊\n- PCI后长期随访\n- 稳定期患者管理\n- 慢病教育\n- 专家学术科普\n\n---\n\n## 05｜从“抗血小板”到“双通道抗栓”：冠心病长期管理的新视角\n\n### 建议标题\n\n- **《血栓并非只有一条来路》**\n- **《当两条血栓通路交汇：重新理解冠心病的长期保护》**\n- **《从一条通路，到双重守护：抗栓策略的另一种思考》**\n- **《不止于血小板：寻找残余血栓风险背后的另一条路径》**\n\n### 话题简要说明\n\n从血栓形成机制切入，解释抗凝与抗血小板两条通路在特定冠心病患者长期管理中的临床意义，为后续介绍相关治疗理念和循证证据建立认知基础。\n\n### 品牌优势体现\n\n该方向能够较好体现拜瑞妥在冠心病长期管理中的差异化内容切入点，尤其适合承接更偏学术教育和机制阐释类的内容表达，增强品牌的专业识别度。\n\n### 医生使用场景匹配度\n\n**★★★★☆ 较高**\n\n适合场景：\n\n- 冠心病高风险患者管理\n- 机制型学术内容\n- 专家教育\n- 循证医学传播\n- 品牌学术活动\n\n---\n\n## 06｜从冠心病到“泛血管”：心内科医生为什么需要重新认识全身血栓风险？\n\n### 建议标题\n\n- **《心脏之外，风险仍在血管中延伸》**\n- **《从一颗心脏，看见一张全身血管网络》**\n- **《当动脉粥样硬化不只发生在冠脉》**\n- **《一处病变，全身风险：重新认识心血管疾病的边界》**\n\n### 话题简要说明\n\n将视角从单纯冠心病扩展到不同血管床的动脉粥样硬化风险，帮助医生从整体患者管理角度理解冠脉、脑血管及外周血管风险之间的关联，强化“全身血管管理”理念。\n\n### 品牌优势体现\n\n这一方向能够帮助拜瑞妥从单一疾病管理延展到更高层次的疾病教育与泛血管风险管理视角，提升品牌内容的战略高度和学术广度。\n\n### 医生使用场景匹配度\n\n**★★★★☆ 较高**\n\n适合场景：\n\n- 综合心血管管理\n- 多病种共病患者教育\n- 品牌疾病教育\n- 跨学科学术传播\n- 泛血管管理主题活动\n\n---\n\n## 推荐优先级\n\n### TOP 1｜房颤患者的卒中预防\n\n**推荐理由：**\n\n- 临床需求最明确\n- 医生关注度最高\n- 与品牌应用场景契合度强\n- 适合作为首批重点内容方向\n\n### TOP 2｜房颤长期抗凝管理\n\n**推荐理由：**\n\n- 容易形成系列内容\n- 可持续运营\n- 有利于体现品牌长期管理价值\n- 适合门诊教育和慢病场景\n\n### TOP 3｜慢性冠心病长期风险\n\n**推荐理由：**\n\n- 认知反差明显，内容更容易吸引注意\n- 适合做学术+传播兼顾型内容\n- 品牌优势表达自然\n\n### TOP 4｜房颤合并冠心病\n\n**推荐理由：**\n\n- 临床复杂度高\n- 适合专业内容深化\n- 专家讨论价值强\n\n### TOP 5｜双通道抗栓\n\n**推荐理由：**\n\n- 适合机制与证据类教育\n- 能体现较强的专业学术属性\n- 对目标医生人群有一定吸引力\n\n### TOP 6｜泛血管管理\n\n**推荐理由：**\n\n- 更偏品牌战略性教育\n- 适合中长期内容布局\n- 可提升品牌整体疾病教育高度\n\n---\n\n## 评分说明\n\n“医生使用场景匹配度”为话题洞察示例评分，可综合以下维度进行评估：\n\n- 医生关注度\n- 临床价值\n- 品牌关联度\n- 内容新鲜度\n- 传播潜力\n- 系列化延展能力\n\n以上评分仅用于内容优先级判断，可根据品牌策略、目标受众、渠道属性及传播目标进一步微调。";

/** 触发：帮我生成五到六个话题（不依赖附件） */
export function isTopicInsightGenerateIntent(text: string): boolean {
  const t = text.replace(/\s+/g, '');
  return (
    /帮我生成[五5]到?[六6]个话题/.test(t) ||
    /生成[五5]到[六6]个话题/.test(t) ||
    /生成[五5]-[六6]个话题/.test(t) ||
    /帮我生成五六个话题/.test(t)
  );
}

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function formatInlineMarkdown(text: string): string {
  return escapeHtml(text).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
}

/** 将洞察 Markdown 转为可编辑的富文本 HTML */
export function markdownToInsightHtml(markdown: string): string {
  const lines = markdown.replace(/\r\n/g, '\n').split('\n');
  const blocks: string[] = [];
  let listItems: string[] = [];

  const flushList = () => {
    if (!listItems.length) return;
    blocks.push(`<ul>${listItems.join('')}</ul>`);
    listItems = [];
  };

  for (const rawLine of lines) {
    const line = rawLine.trimEnd();
    const trimmed = line.trim();

    if (!trimmed) {
      flushList();
      continue;
    }

    if (/^---+$/.test(trimmed)) {
      flushList();
      blocks.push('<hr />');
      continue;
    }

    const heading = /^(#{1,3})\s+(.+)$/.exec(trimmed);
    if (heading) {
      flushList();
      const level = heading[1].length;
      blocks.push(`<h${level}>${formatInlineMarkdown(heading[2])}</h${level}>`);
      continue;
    }

    const bullet = /^[-*]\s+(.+)$/.exec(trimmed);
    if (bullet) {
      listItems.push(`<li>${formatInlineMarkdown(bullet[1])}</li>`);
      continue;
    }

    flushList();
    blocks.push(`<p>${formatInlineMarkdown(trimmed)}</p>`);
  }

  flushList();
  return blocks.join('');
}

/** 若仍是 Markdown 源文，转为 HTML；已是 HTML 则原样返回 */
export function ensureTopicInsightHtml(content: string): string {
  const trimmed = content.trim();
  if (!trimmed) return '';
  if (/^</.test(trimmed) || /<\/(p|h[1-3]|ul|li|strong|hr)>/i.test(trimmed)) {
    return content;
  }
  return markdownToInsightHtml(content);
}

export function htmlToPlainText(html: string): string {
  if (typeof document !== 'undefined') {
    const host = document.createElement('div');
    host.innerHTML = html;
    return (host.innerText || host.textContent || '').trim();
  }
  return html
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|h[1-3]|li|div|hr)>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}
